// Mihomo / Clash.Meta Aliyun front override script.
//
// Inline `proxies` mode keeps the original chained-proxy behavior.
// Provider-only subscriptions generated by the Worker/subconverter chain are
// handled with provider cloning + provider override.
//
// Current rules:
// 1. The Aliyun front pool matches the exact node name "阿里云中转".
// 2. Both front groups only pull VLESS landing nodes.
// 3. The custom VLESS front excludes same-machine nodes.
// 4. Both front groups exclude the Aliyun transit node from candidate selection.

const FRONT_NODE_NAMES = ["阿里云中转"];
const CUSTOM_FRONT_NODE_NAMES = ["家人-日本"];
const TARGET_PROXY_TYPES = ["vless"];
const EXCLUDED_PROVIDER_TYPES = [
  "ss",
  "shadowsocks",
  "ssr",
  "vmess",
  "trojan",
  "tuic",
  "hysteria",
  "hysteria2",
  "hy2",
  "snell",
  "socks5",
  "http",
  "wireguard",
  "ssh",
  "anytls",
  "juicity",
  "mieru",
  "tor",
  "direct",
  "dns",
];
const INSERT_TO_GROUPS = ["PROXY", "Proxy", "GLOBAL"];
const CHAIN_IP_VERSION = "ipv4";
const TRAILING_NODE_INDEX_RE = /(?:[-_\s·.]?\d+)+$/u;
const WORKER_SOURCE_PATH_KEYWORDS = ["/__node_source/"];

const FRONT_SETUPS = [
  {
    key: "aliyun",
    frontNodeNames: FRONT_NODE_NAMES,
    poolGroupName: "__阿里云前置池",
    chainGroupName: "阿里云前置",
    chainNameSuffix: " · 阿里云前置",
    skipSameMachine: false,
  },
  {
    key: "custom",
    frontNodeNames: CUSTOM_FRONT_NODE_NAMES,
    poolGroupName: "__自定义VLESS前置池",
    chainGroupName: "自定义VLESS前置",
    chainNameSuffix: " · 自定义VLESS前置",
    skipSameMachine: true,
  },
];

function main(config) {
  const nextConfig = config || {};
  const proxies = Array.isArray(nextConfig.proxies) ? nextConfig.proxies : [];

  if (proxies.length > 0) {
    return applyInlineProxyMode(nextConfig, proxies);
  }

  return applyProviderMode(nextConfig);
}

function applyInlineProxyMode(config, proxies) {
  const proxyGroups = Array.isArray(config["proxy-groups"]) ? config["proxy-groups"] : [];
  if (!hasExactFrontNode(proxies, FRONT_NODE_NAMES)) {
    return config;
  }

  config.proxies = proxies.filter(proxy => {
    const name = proxy && proxy.name;
    return name && !isGeneratedChainProxy(name);
  });

  config["proxy-groups"] = proxyGroups.filter(group => {
    const name = group && group.name;
    return name && !isGeneratedChainGroup(name);
  });

  const baseProxies = config.proxies;
  const baseGroups = config["proxy-groups"];
  const appendedProxies = [];
  const appendedGroups = [];
  const insertedGroupNames = [];

  for (const setup of FRONT_SETUPS) {
    const activeFrontNodes = baseProxies.filter(proxy => isFrontNode(proxy && proxy.name, setup.frontNodeNames));
    if (!activeFrontNodes.length) {
      continue;
    }

    const activeFrontNames = unique(activeFrontNodes.map(proxy => proxy.name));
    const frontMachineKeys = setup.skipSameMachine
      ? unique(activeFrontNames.map(getMachineKey))
      : [];

    const chainCandidates = baseProxies.filter(proxy =>
      shouldChainProxy(proxy, setup, activeFrontNames, frontMachineKeys)
    );
    if (!chainCandidates.length) {
      continue;
    }

    const chainedProxies = chainCandidates.map(proxy => buildChainedProxy(proxy, setup));
    const chainProxyNames = chainedProxies.map(proxy => proxy.name);

    appendedProxies.push(...chainedProxies);
    appendedGroups.push({
      name: setup.poolGroupName,
      type: "select",
      proxies: activeFrontNames,
      hidden: true,
    });
    appendedGroups.push({
      name: setup.chainGroupName,
      type: "select",
      proxies: chainProxyNames,
    });
    insertedGroupNames.push(setup.chainGroupName);
  }

  if (!appendedProxies.length) {
    return config;
  }

  config.proxies = baseProxies.concat(appendedProxies);
  config["proxy-groups"] = baseGroups.concat(appendedGroups);
  insertGroupsIntoTargets(config["proxy-groups"], insertedGroupNames);
  return config;
}

function applyProviderMode(config) {
  const providers = config["proxy-providers"];
  if (!providers || typeof providers !== "object") {
    return config;
  }

  const baseProviderNames = Object.keys(providers).filter(name => !isGeneratedProviderName(name));
  if (!baseProviderNames.length) {
    return config;
  }

  const sourceProviderNames = baseProviderNames.filter(name => isWorkerNodeSourceProvider(providers[name]));
  if (!sourceProviderNames.length) {
    return config;
  }

  config["proxy-groups"] = Array.isArray(config["proxy-groups"]) ? config["proxy-groups"] : [];
  config["proxy-groups"] = config["proxy-groups"].filter(group => {
    const name = group && group.name;
    return name && !isGeneratedChainGroup(name);
  });

  for (const providerName of Object.keys(providers)) {
    if (isGeneratedProviderName(providerName)) {
      delete providers[providerName];
    }
  }

  const insertedGroupNames = [];
  for (const setup of FRONT_SETUPS) {
    const clonedProviderNames = [];
    for (const baseProviderName of sourceProviderNames) {
      const baseProvider = providers[baseProviderName];
      if (!baseProvider) {
        continue;
      }

      const clonedProviderName = makeGeneratedProviderName(baseProviderName, setup.key);
      providers[clonedProviderName] = buildChainedProvider(baseProvider, setup.poolGroupName);
      clonedProviderNames.push(clonedProviderName);
    }

    if (!clonedProviderNames.length) {
      continue;
    }

    config["proxy-groups"].push(buildFrontPoolGroup(sourceProviderNames, setup));
    config["proxy-groups"].push(buildProviderChainGroup(clonedProviderNames, setup));
    insertedGroupNames.push(setup.chainGroupName);
  }

  if (!insertedGroupNames.length) {
    return config;
  }

  insertGroupsIntoTargets(config["proxy-groups"], insertedGroupNames);
  return config;
}

function buildFrontPoolGroup(providerNames, setup) {
  return {
    name: setup.poolGroupName,
    type: "select",
    use: providerNames,
    filter: buildExactNameFilter(setup.frontNodeNames),
    proxies: ["DIRECT"],
    hidden: true,
  };
}

function buildProviderChainGroup(providerNames, setup) {
  return {
    name: setup.chainGroupName,
    type: "select",
    use: providerNames,
    filter: buildCandidateFilter(setup),
    proxies: ["DIRECT"],
  };
}

function buildChainedProvider(provider, poolGroupName) {
  const cloned = deepClone(provider);
  const existingOverride = cloned.override && typeof cloned.override === "object" ? cloned.override : {};
  cloned.override = {
    ...existingOverride,
    "dialer-proxy": poolGroupName,
    "ip-version": CHAIN_IP_VERSION,
  };
  cloned["exclude-type"] = mergeExcludedProviderTypes(cloned["exclude-type"]);
  return cloned;
}

function mergeExcludedProviderTypes(existingValue) {
  const existingTypes = String(existingValue || "")
    .split("|")
    .map(type => type.trim().toLowerCase())
    .filter(Boolean);

  const merged = unique(existingTypes.concat(EXCLUDED_PROVIDER_TYPES));
  return merged.join("|");
}

function insertGroupsIntoTargets(groups, insertedGroupNames) {
  for (const group of groups) {
    if (!group || !INSERT_TO_GROUPS.includes(group.name)) {
      continue;
    }

    group.proxies = Array.isArray(group.proxies) ? group.proxies : [];
    for (const insertedGroupName of insertedGroupNames.slice().reverse()) {
      if (!group.proxies.includes(insertedGroupName)) {
        group.proxies.unshift(insertedGroupName);
      }
    }
  }
}

function buildChainedProxy(proxy, setup) {
  const chained = deepClone(proxy);
  chained.name = makeChainName(proxy.name, setup.chainNameSuffix);
  chained["dialer-proxy"] = setup.poolGroupName;
  chained["ip-version"] = CHAIN_IP_VERSION;
  delete chained.interface;
  return chained;
}

function shouldChainProxy(proxy, setup, activeFrontNames, frontMachineKeys) {
  if (!proxy || !proxy.name || !proxy.type) {
    return false;
  }

  if (activeFrontNames.includes(proxy.name)) {
    return false;
  }

  if (isGeneratedChainProxy(proxy.name)) {
    return false;
  }

  if (isLiteralIPv6(proxy.server)) {
    return false;
  }

  if (isAnyAliyunTransitNode(proxy.name)) {
    return false;
  }

  if (!isTargetVlessProxy(proxy)) {
    return false;
  }

  if (setup.skipSameMachine) {
    const proxyMachineKey = getMachineKey(proxy.name);
    if (proxyMachineKey && frontMachineKeys.includes(proxyMachineKey)) {
      return false;
    }
  }

  return true;
}

function hasExactFrontNode(proxies, frontNodeNames) {
  return Array.isArray(proxies) && proxies.some(proxy => isFrontNode(proxy && proxy.name, frontNodeNames));
}

function isFrontNode(name, frontNodeNames) {
  return Array.isArray(frontNodeNames) && frontNodeNames.includes(name);
}

function isAnyAliyunTransitNode(name) {
  return isFrontNode(name, FRONT_NODE_NAMES);
}

function isTargetVlessProxy(proxy) {
  const type = String(proxy && proxy.type ? proxy.type : "").toLowerCase();
  return TARGET_PROXY_TYPES.includes(type);
}

function isGeneratedChainProxy(name) {
  return typeof name === "string" && FRONT_SETUPS.some(setup => name.endsWith(setup.chainNameSuffix));
}

function isGeneratedChainGroup(name) {
  return FRONT_SETUPS.some(setup => name === setup.poolGroupName || name === setup.chainGroupName);
}

function isGeneratedProviderName(name) {
  return typeof name === "string" && name.startsWith("__front_provider__");
}

function makeGeneratedProviderName(baseProviderName, key) {
  return `__front_provider__${key}__${baseProviderName}`;
}

function makeChainName(name, suffix) {
  return `${name}${suffix}`;
}

function getMachineKey(name) {
  if (typeof name !== "string") {
    return "";
  }

  const trimmed = name.trim();
  if (!trimmed) {
    return "";
  }

  const withoutIndex = trimmed.replace(TRAILING_NODE_INDEX_RE, "").trim();
  return (withoutIndex || trimmed).toLowerCase();
}

function unique(list) {
  return Array.from(new Set(list.filter(Boolean)));
}

function isLiteralIPv6(server) {
  return typeof server === "string" && server.includes(":") && !server.includes(".");
}

function isWorkerNodeSourceProvider(provider) {
  const url = String(provider && provider.url ? provider.url : "").trim();
  if (!url) {
    return false;
  }

  return WORKER_SOURCE_PATH_KEYWORDS.some(keyword => url.includes(keyword));
}

function buildExactNameFilter(names) {
  const escaped = names.map(escapeRegExp).filter(Boolean);
  if (!escaped.length) {
    return "^$";
  }
  return `^(?:${escaped.join("|")})$`;
}

function buildCandidateFilter(setup) {
  const excludedPatterns = FRONT_NODE_NAMES.map(escapeRegExp).filter(Boolean);

  if (setup.skipSameMachine) {
    const sameMachinePatterns = setup.frontNodeNames
      .map(name => {
        const machineKey = getMachineKey(name);
        return machineKey ? `${escapeRegExp(machineKey)}(?:[-_\\s·.]?\\d+)*` : "";
      })
      .filter(Boolean);
    excludedPatterns.push(...sameMachinePatterns);
  }

  const negative = excludedPatterns.length ? `(?!^(?:${excludedPatterns.join("|")})$)` : "";
  return `${negative}.+`;
}

function escapeRegExp(value) {
  return typeof value === "string" && value
    ? value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    : "";
}

function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}
